import 'dart:convert';

/// Who a birthday template is written for.
abstract final class BirthdayAudience {
  static const student = 'student';
  static const parent = 'parent';
  static const all = [student, parent];
}

/// One saved wish template. Ids are generated by the app, so the API only stores them.
class BirthdayTemplate {
  final String id;
  final String name;
  final String body;

  /// [BirthdayAudience.student] or [BirthdayAudience.parent].
  final String audience;

  const BirthdayTemplate({
    required this.id,
    required this.name,
    required this.body,
    required this.audience,
  });

  factory BirthdayTemplate.fromJson(Map<String, dynamic> json) {
    final audience = '${json['audience'] ?? ''}';
    return BirthdayTemplate(
      id: '${json['id'] ?? ''}',
      name: '${json['name'] ?? ''}',
      body: '${json['body'] ?? ''}',
      audience: audience == BirthdayAudience.parent ? BirthdayAudience.parent : BirthdayAudience.student,
    );
  }

  Map<String, dynamic> toJson() => {'id': id, 'name': name, 'body': body, 'audience': audience};

  BirthdayTemplate copyWith({String? name, String? body}) =>
      BirthdayTemplate(id: id, name: name ?? this.name, body: body ?? this.body, audience: audience);

  /// Parses a `templates` value that may arrive as a list or as a JSON string (MySQL JSON column).
  static List<BirthdayTemplate> listFromJson(dynamic raw) {
    var value = raw;
    if (value is String && value.trim().isNotEmpty) {
      try {
        value = jsonDecode(value);
      } catch (_) {
        return const [];
      }
    }
    if (value is! List) return const [];
    return value
        .whereType<Map>()
        .map((e) => BirthdayTemplate.fromJson(Map<String, dynamic>.from(e)))
        .where((t) => t.id.isNotEmpty)
        .toList();
  }
}

class BirthdayConfigModel {
  final int id;
  final bool isEnabled;
  final String sendTime;
  final String targetAudience;
  final bool preferWhatsAppNumber;
  final String? adminNotificationPhone;

  /// Body of the active student template: what the server sends to students.
  final String messageTemplate;

  /// Body of the active parent template: what the server sends to parents.
  /// Empty until the API supports it (it then falls back to [messageTemplate]).
  final String parentMessageTemplate;

  /// The full template library and the active pick per audience.
  final List<BirthdayTemplate> templates;
  final String? activeStudentTemplateId;
  final String? activeParentTemplateId;

  /// Whether the API returned a `templates` field. While it doesn't (older hsh_api),
  /// the app keeps the library in a local cache instead.
  final bool templatesFromServer;

  final String? imageUrl;
  final String? lastRunDate;

  const BirthdayConfigModel({
    this.id = 1,
    this.isEnabled = true,
    this.sendTime = '08:00',
    this.targetAudience = 'student_only',
    this.preferWhatsAppNumber = true,
    this.adminNotificationPhone,
    this.messageTemplate =
        'Dear {student_name}, 🎂🎉 Wishing you a very Happy Birthday from Hari Saurabh Hostel family! May your special day bring you immense joy, good health, and success! 🌟✨ - HSH Warden Team',
    this.parentMessageTemplate = '',
    this.templates = const [],
    this.activeStudentTemplateId,
    this.activeParentTemplateId,
    this.templatesFromServer = false,
    this.imageUrl,
    this.lastRunDate,
  });

  factory BirthdayConfigModel.fromJson(Map<String, dynamic> json) {
    final rawTemplates = json['templates'] ?? json['message_templates'];
    return BirthdayConfigModel(
      id: json['id'] is int ? json['id'] : int.tryParse('${json['id']}') ?? 1,
      isEnabled: json['isEnabled'] == true || json['is_enabled'] == 1 || json['isEnabled'] == 1,
      sendTime: json['sendTime'] ?? json['send_time'] ?? '08:00',
      targetAudience: json['targetAudience'] ?? json['target_audience'] ?? 'student_only',
      preferWhatsAppNumber: json['preferWhatsAppNumber'] == true ||
          json['prefer_whatsapp_number'] == 1 ||
          json['preferWhatsAppNumber'] == 1,
      adminNotificationPhone: json['adminNotificationPhone'] ?? json['admin_notification_phone'],
      messageTemplate: json['messageTemplate'] ?? json['message_template'] ?? '',
      parentMessageTemplate: json['parentMessageTemplate'] ?? json['parent_message_template'] ?? '',
      templates: BirthdayTemplate.listFromJson(rawTemplates),
      activeStudentTemplateId: _idOrNull(json['activeStudentTemplateId'] ?? json['active_student_template_id']),
      activeParentTemplateId: _idOrNull(json['activeParentTemplateId'] ?? json['active_parent_template_id']),
      templatesFromServer: rawTemplates != null,
      imageUrl: json['imageUrl'] ?? json['image_url'],
      lastRunDate: json['lastRunDate'] != null ? '${json['lastRunDate']}'.split('T').first : null,
    );
  }

  static String? _idOrNull(dynamic v) => (v == null || '$v'.isEmpty) ? null : '$v';

  Map<String, dynamic> toJson() {
    return {
      'isEnabled': isEnabled,
      'sendTime': sendTime,
      'targetAudience': targetAudience,
      'preferWhatsAppNumber': preferWhatsAppNumber,
      'adminNotificationPhone': adminNotificationPhone,
      'messageTemplate': messageTemplate,
      'parentMessageTemplate': parentMessageTemplate,
      'templates': templates.map((t) => t.toJson()).toList(),
      'activeStudentTemplateId': activeStudentTemplateId,
      'activeParentTemplateId': activeParentTemplateId,
      'imageUrl': imageUrl,
    };
  }

  BirthdayConfigModel copyWith({
    bool? isEnabled,
    String? sendTime,
    String? targetAudience,
    bool? preferWhatsAppNumber,
    String? adminNotificationPhone,
    String? messageTemplate,
    String? parentMessageTemplate,
    List<BirthdayTemplate>? templates,
    String? activeStudentTemplateId,
    String? activeParentTemplateId,
    String? imageUrl,
  }) {
    return BirthdayConfigModel(
      id: id,
      isEnabled: isEnabled ?? this.isEnabled,
      sendTime: sendTime ?? this.sendTime,
      targetAudience: targetAudience ?? this.targetAudience,
      preferWhatsAppNumber: preferWhatsAppNumber ?? this.preferWhatsAppNumber,
      adminNotificationPhone: adminNotificationPhone ?? this.adminNotificationPhone,
      messageTemplate: messageTemplate ?? this.messageTemplate,
      parentMessageTemplate: parentMessageTemplate ?? this.parentMessageTemplate,
      templates: templates ?? this.templates,
      activeStudentTemplateId: activeStudentTemplateId ?? this.activeStudentTemplateId,
      activeParentTemplateId: activeParentTemplateId ?? this.activeParentTemplateId,
      templatesFromServer: templatesFromServer,
      imageUrl: imageUrl ?? this.imageUrl,
      lastRunDate: lastRunDate,
    );
  }
}

class BirthdayStudentModel {
  final int studentId;
  final String name;
  final String studentCode;
  final String phone;
  final String whatsappNumber;
  final String parentPhone;
  final String room;
  final String dob;
  final bool alreadySentToday;
  final bool isActive;

  /// Group (Param, Pavitra, ...) and hostel status, when the API sends them.
  /// The admin screen falls back to the phonebook synced on the phone.
  final String? groupName;
  final String? status;

  const BirthdayStudentModel({
    required this.studentId,
    required this.name,
    required this.studentCode,
    this.phone = '',
    this.whatsappNumber = '',
    this.parentPhone = '',
    this.room = 'N/A',
    this.dob = '',
    this.alreadySentToday = false,
    this.isActive = true,
    this.groupName,
    this.status,
  });

  /// Same rule as the phonebook: no room, inactive, or a left/alumni status.
  bool get isAlumni {
    final r = room.toLowerCase().trim();
    return !isActive || r.isEmpty || r == 'n/a' || r == 'alumni' || statusMeansAlumni(status);
  }

  static bool statusMeansAlumni(String? status) {
    final s = (status ?? '').toLowerCase();
    return s.contains('alumni') || s.contains('left') || s.contains('cancel');
  }

  factory BirthdayStudentModel.fromJson(Map<String, dynamic> json) {
    return BirthdayStudentModel(
      studentId: json['studentId'] is int
          ? json['studentId']
          : int.tryParse('${json['studentId'] ?? json['student_id']}') ?? 0,
      name: (json['name'] ?? 'Student').toString(),
      studentCode: (json['studentCode'] ?? json['student_code'] ?? '').toString(),
      phone: (json['phone'] ?? json['phone_number'] ?? '').toString(),
      whatsappNumber: (json['whatsappNumber'] ?? json['whatsapp_number'] ?? json['phone'] ?? '').toString(),
      parentPhone: (json['parentPhone'] ?? json['parent_phone'] ?? '').toString(),
      room: (json['room'] ?? json['room_number'] ?? 'N/A').toString(),
      dob: json['dob'] != null ? '${json['dob']}'.split('T').first : '',
      alreadySentToday: json['alreadySentToday'] == true || json['already_sent_today'] == 1,
      isActive: json['isActive'] != false && json['is_active'] != 0,
      groupName: _textOrNull(json['groupName'] ?? json['group_name']),
      status: _textOrNull(json['status']),
    );
  }

  static String? _textOrNull(dynamic v) {
    final text = v?.toString().trim() ?? '';
    return text.isEmpty ? null : text;
  }
}

class BirthdayLogModel {
  final int id;
  final int studentId;
  final String studentName;
  final String studentCode;
  final String room;
  final String wishDate;
  final String phone;
  final String recipientType;
  final String message;
  final String status;
  final String sentAt;

  const BirthdayLogModel({
    required this.id,
    required this.studentId,
    required this.studentName,
    required this.studentCode,
    required this.room,
    required this.wishDate,
    required this.phone,
    required this.recipientType,
    required this.message,
    required this.status,
    required this.sentAt,
  });

  factory BirthdayLogModel.fromJson(Map<String, dynamic> json) {
    return BirthdayLogModel(
      id: json['id'] is int ? json['id'] : int.tryParse('${json['id']}') ?? 0,
      studentId: json['studentId'] is int
          ? json['studentId']
          : int.tryParse('${json['studentId'] ?? json['student_id']}') ?? 0,
      studentName: (json['studentName'] ?? json['student_name'] ?? 'Student').toString(),
      studentCode: (json['studentCode'] ?? json['student_code'] ?? '').toString(),
      room: (json['room'] ?? json['room_number'] ?? 'N/A').toString(),
      wishDate: json['wishDate'] != null ? '${json['wishDate']}'.split('T').first : '',
      phone: (json['phone'] ?? '').toString(),
      recipientType: (json['recipientType'] ?? json['recipient_type'] ?? 'student').toString(),
      message: (json['message'] ?? '').toString(),
      status: (json['status'] ?? 'sent').toString(),
      sentAt: (json['sentAt'] ?? json['sent_at'] ?? '').toString(),
    );
  }

  bool get isSent => status.toLowerCase() == 'sent';
}

class BirthdayDashboardData {
  final BirthdayConfigModel config;
  final List<BirthdayStudentModel> todaysBirthdays;
  final List<BirthdayStudentModel> tomorrowsBirthdays;
  final List<BirthdayLogModel> recentLogs;
  final bool isWhatsAppConnected;
  final String? senderPhone;

  const BirthdayDashboardData({
    required this.config,
    required this.todaysBirthdays,
    required this.tomorrowsBirthdays,
    required this.recentLogs,
    required this.isWhatsAppConnected,
    this.senderPhone,
  });

  factory BirthdayDashboardData.fromJson(Map<String, dynamic> json) {
    final cfg = json['config'] is Map
        ? BirthdayConfigModel.fromJson(Map<String, dynamic>.from(json['config']))
        : const BirthdayConfigModel();
    final todayList = (json['todaysBirthdays'] as List?)
            ?.map((e) => BirthdayStudentModel.fromJson(Map<String, dynamic>.from(e)))
            .toList() ??
        [];
    final tomorrowList = (json['tomorrowsBirthdays'] as List?)
            ?.map((e) => BirthdayStudentModel.fromJson(Map<String, dynamic>.from(e)))
            .toList() ??
        [];
    final logsList = (json['recentLogs'] as List?)
            ?.map((e) => BirthdayLogModel.fromJson(Map<String, dynamic>.from(e)))
            .toList() ??
        [];

    return BirthdayDashboardData(
      config: cfg,
      todaysBirthdays: todayList,
      tomorrowsBirthdays: tomorrowList,
      recentLogs: logsList,
      isWhatsAppConnected: json['isWhatsAppConnected'] == true,
      senderPhone: json['senderPhone']?.toString(),
    );
  }
}
